#![allow(non_snake_case)] // Uppercase identifiers denote curve points.

use crate::common::{
    parse_coordinator_msg1, parse_coordinator_msg2, parse_hex_array, parse_participant_msg1,
    parse_point_hex, serialize_recovery_data,
};
use chilldkg_rs::coordinator::{CoordinatorInitialState, CoordinatorState};
use chilldkg_rs::errors::ChillDkgError::{FaultyParticipantError, ValueError};
use chilldkg_rs::msg::ParticipantMsg2;

pub mod common;

#[test]
fn test_coordinator_finalize_passes() {
    let hostpubkeys = vec![
        parse_point_hex("03AED316469060698D774150EFD7F8F406A2BAB516DD7D22CB258323C59C6417F3")
            .unwrap(),
        parse_point_hex("03AEB5AE20783D4858F6767747963F144C7DB8ABA328625CC8A87F7676D8CDEEE7")
            .unwrap(),
        parse_point_hex("021A48BBCCAC751AE9EC1EA7A7F8D421D5FD60AAB44E6D2F37B31873098A77B7A3")
            .unwrap(),
    ];

    let t = 2;
    let n = hostpubkeys.len();
    let pmsgs1 = vec![
        parse_participant_msg1("", t, n).unwrap(),
        parse_participant_msg1("", t, n).unwrap(),
        parse_participant_msg1("", t, n).unwrap(),
    ];

    let expected_cmsg1 = parse_coordinator_msg1("", t, n).unwrap();

    let pmsgs2 = vec![
        ParticipantMsg2 {
            sig: parse_hex_array("A6C2DE535556E47C8F3427B9716CFC4A66ADD0F2788AB793E2FBFF7D81DA06315C3F62CAA2B85E369922E68A94113EB839B5E3E424A4F4BF2E8D2908F517E8BE").unwrap(),
        },
        ParticipantMsg2 {
            sig: parse_hex_array("3B1B96C40D7F9A378F2A61FACF8469447344B5280F5E7B3C66B560709A6FA4D7E083E650F3C109995ACB96EEA2EE4EF252257E1BF92FFF121CE916DE2D7C4B54").unwrap(),
        },
        ParticipantMsg2 {
            sig: parse_hex_array("79195E7CBE22A8B53C41012ABEA37F0B59579E43EDC6477E8CC5C7EB9F3C8BF7AEC850C63A659FADD91C9063908054FC4D193594E132ADFBE1F24BE74C8BEA7A").unwrap(),
        },
    ];

    let expected_cmsg2 = parse_coordinator_msg2("").unwrap();

    let threshold_pubkey =
        parse_point_hex("021979452A2E878B2A5BB662F293D23C5795991FB984A8DFDE6EAA885AB72B311A")
            .unwrap();

    let pubshares = vec![
        parse_point_hex("03D5DF677B4FD40950902A2D3D6469723FADCE0CDD939C8150937EF1D15801DDBC")
            .unwrap(),
        parse_point_hex("03B53DF94A01A578300EBB5095B36668E810FE030C200F887CD9BD7F3AD40F31CA")
            .unwrap(),
        parse_point_hex("0377FADE50E2F82A4FD697CF403F8C717E8614199AA87458BCB8A16E6289C26F8B")
            .unwrap(),
    ];

    let recovery_data_hex = "";

    let initial = CoordinatorInitialState::new(hostpubkeys, t).unwrap();
    let (next, actual_cmsg1) = initial.next(pmsgs1).unwrap();
    assert_eq!(actual_cmsg1, expected_cmsg1);

    let (_, (cmsg2, dkg_output, recovery_data)) = next.unwrap().next(pmsgs2).unwrap();
    assert_eq!(cmsg2, expected_cmsg2);
    assert_eq!(dkg_output.t, t);
    assert_eq!(dkg_output.threshold_pubkey, threshold_pubkey);
    assert_eq!(dkg_output.pubshares, pubshares);
    assert_eq!(
        hex::encode_upper(serialize_recovery_data(&recovery_data)),
        recovery_data_hex
    );
}

#[test]
fn test_coordinator_finalize_rejects_invalid_pmsg2_count() {
    let hostpubkeys = vec![
        parse_point_hex("03AED316469060698D774150EFD7F8F406A2BAB516DD7D22CB258323C59C6417F3")
            .unwrap(),
        parse_point_hex("03AEB5AE20783D4858F6767747963F144C7DB8ABA328625CC8A87F7676D8CDEEE7")
            .unwrap(),
        parse_point_hex("021A48BBCCAC751AE9EC1EA7A7F8D421D5FD60AAB44E6D2F37B31873098A77B7A3")
            .unwrap(),
    ];
    let t = 2;
    let n = hostpubkeys.len();
    let pmsgs1 = vec![
        parse_participant_msg1("", t, n).unwrap(),
        parse_participant_msg1("", t, n).unwrap(),
        parse_participant_msg1("", t, n).unwrap(),
    ];
    let cmsg1 = parse_coordinator_msg1("", t, n).unwrap();
    let pmsgs2 = vec![
        ParticipantMsg2 {
            sig: parse_hex_array("A6C2DE535556E47C8F3427B9716CFC4A66ADD0F2788AB793E2FBFF7D81DA06315C3F62CAA2B85E369922E68A94113EB839B5E3E424A4F4BF2E8D2908F517E8BE").unwrap(),
        },
        ParticipantMsg2 {
            sig: parse_hex_array("3B1B96C40D7F9A378F2A61FACF8469447344B5280F5E7B3C66B560709A6FA4D7E083E650F3C109995ACB96EEA2EE4EF252257E1BF92FFF121CE916DE2D7C4B54").unwrap(),
        },
    ];

    let initial = CoordinatorInitialState::new(hostpubkeys, t).unwrap();
    let (next, actual_cmsg1) = initial.next(pmsgs1).unwrap();
    assert_eq!(actual_cmsg1, cmsg1);
    let err = next.unwrap().next(pmsgs2).unwrap_err();
    assert_eq!(
        err,
        ValueError("Coordinator step 2 received invalid number of participant messages".to_owned())
    );
}

#[test]
fn test_coordinator_finalize_rejects_invalid_signature() {
    let hostpubkeys = vec![
        parse_point_hex("03AED316469060698D774150EFD7F8F406A2BAB516DD7D22CB258323C59C6417F3")
            .unwrap(),
        parse_point_hex("03AEB5AE20783D4858F6767747963F144C7DB8ABA328625CC8A87F7676D8CDEEE7")
            .unwrap(),
        parse_point_hex("021A48BBCCAC751AE9EC1EA7A7F8D421D5FD60AAB44E6D2F37B31873098A77B7A3")
            .unwrap(),
    ];
    let t = 2;
    let n = hostpubkeys.len();
    let pmsgs1 = vec![
        parse_participant_msg1("", t, n).unwrap(),
        parse_participant_msg1("", t, n).unwrap(),
        parse_participant_msg1("", t, n).unwrap(),
    ];
    let cmsg1 = parse_coordinator_msg1("", t, n).unwrap();
    let pmsgs2 = vec![
        ParticipantMsg2 {
            sig: parse_hex_array("A6C2DE535556E47C8F3427B9716CFC4A66ADD0F2788AB793E2FBFF7D81DA06315C3F62CAA2B85E369922E68A94113EB839B5E3E424A4F4BF2E8D2908F517E8BE").unwrap(),
        },
        ParticipantMsg2 {
            sig: parse_hex_array("09C289578B96E6283AB13E4741FB489FC147FB1A5F446A314BA73C052131EFB04B83247A0BCEDF5205202AD64188B24B0BC5B51A17AEB218BD98DBE000C843B9").unwrap(),
        },
        ParticipantMsg2 {
            sig: parse_hex_array("79195E7CBE22A8B53C41012ABEA37F0B59579E43EDC6477E8CC5C7EB9F3C8BF7AEC850C63A659FADD91C9063908054FC4D193594E132ADFBE1F24BE74C8BEA7A").unwrap(),
        },
    ];

    let initial = CoordinatorInitialState::new(hostpubkeys, t).unwrap();
    let (next, actual_cmsg1) = initial.next(pmsgs1).unwrap();
    assert_eq!(actual_cmsg1, cmsg1);
    let err = next.unwrap().next(pmsgs2).unwrap_err();
    assert_eq!(
        err,
        FaultyParticipantError {
            participant: 1,
            message: "Participant has provided an invalid signature for the certificate, error = RuntimeError(\"Schnorr verification failed: invalid signature\")".to_owned(),
        }
    );
}
